from __future__ import annotations
from copy import deepcopy
import numpy as np
import pandas as pd


MUTATIONS = (
    "index_shift", "target_swap", "horizon_truncation", "nonfinite_point",
    "quantile_crossing", "sample_axis_swap", "variance_shrink", "dependence_shuffle",
)

# %% auto #0
__all__ = ['MUTATIONS', 'mutate_forecast']

# %% ../notebooks/09_scores_and_diagnostics.ipynb #09_scores_and_diagno-48
def mutate_forecast(forecast, name, *, seed=0, enabled=True, strength=1.0):
    """Return a copy with one known fault; enabled=False is its paired repair.

dependence_shuffle independently permutes a fraction of the ensemble within
each (horizon,target) coordinate. Every marginal empirical distribution stays
exactly unchanged at every strength in [0,1].
    """
    if name not in MUTATIONS:
        raise ValueError(f"Unknown mutation: {name}")
    if not 0 <= strength <= 1:
        raise ValueError("strength must be between zero and one")
    result = deepcopy(forecast)
    if not enabled:
        return result
    for attr in ("point", "quantiles", "samples"):
        value = getattr(result, attr)
        if value is not None:
            setattr(result, attr, np.asarray(value, dtype=float).copy())
    if name == "index_shift":
        if not pd.api.types.is_integer_dtype(result.index.dtype):
            raise ValueError("index_shift fixture requires an integer index")
        result.index = result.index + 1
    elif name == "target_swap":
        if len(result.target_names) < 2:
            raise ValueError("target_swap requires two or more targets")
        result.target_names = tuple(reversed(result.target_names))
    elif name == "horizon_truncation":
        result.index = result.index[:-1]
        for attr in ("point", "quantiles"):
            value = getattr(result, attr)
            if value is not None:
                setattr(result, attr, value[:-1])
        if result.samples is not None:
            result.samples = result.samples[:, :-1]
    elif name == "nonfinite_point":
        if result.point is None:
            raise ValueError("nonfinite_point requires explicit point forecasts")
        result.point[0, 0] = np.nan
    elif name == "quantile_crossing":
        if result.quantiles is None or result.quantiles.shape[-1] < 2 or not np.any(np.diff(result.quantiles, axis=-1) > 0):
            raise ValueError("quantile_crossing requires at least two distinct ordered quantiles")
        result.quantiles = result.quantiles[..., ::-1].copy()
    elif name == "sample_axis_swap":
        if result.samples is None or result.samples.shape[0] == result.samples.shape[1]:
            raise ValueError("sample_axis_swap requires samples with sample count different from horizon")
        result.samples = result.samples.transpose(1, 0, 2)
    elif name == "variance_shrink":
        if result.point is None or result.samples is None or result.quantiles is None:
            raise ValueError("variance_shrink requires point, sample, and quantile outputs")
        result.samples = result.point[None] + 0.25 * (result.samples - result.point[None])
        result.quantiles = result.point[..., None] + 0.25 * (result.quantiles - result.point[..., None])
    elif name == "dependence_shuffle":
        if result.samples is None:
            raise ValueError("dependence_shuffle requires predictive samples")
        rng = np.random.default_rng(seed)
        s, h, d = result.samples.shape
        count = int(round(s * strength))
        for i in range(h):
            for j in range(d):
                indices = rng.choice(s, count, replace=False)
                result.samples[indices, i, j] = result.samples[rng.permutation(indices), i, j]
    return result
